List<String> fruits = ['Apple', 'Banana', 'Mango'];

fruits.add('Orange');
fruits.remove('Banana');

for (final fruit in fruits) {
  print(fruit);
}

final upperFruits = fruits.map((f) => f.toUpperCase()).toList();
final aFruits = fruits.where((f) => f.startsWith('A')).toList();
final sortedFruits = [...fruits]..sort();

final Set<String> fruits = {'Apple', 'Banana', 'Mango', 'Apple'};
// Duplicate 'Apple' is ignored
fruits.add('Orange');
final bool hasMango = fruits.contains('Mango');
